Method.Implementation:
	set tSC = $$$OK
	try {
		set message = ""
		set recId = ""


		&SQL(SELECT * FROM IHC_ITF_TPManage.TradingPartner)

		#dim rs As %SQL.Statement
		Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT ID, CKPYREFID, Status FROM IHC_ITF_DStruc.DndCoreEraRecord where Status in ('Ready', 'EndOfRun') ORDER BY ID")

		While rs.%Next() {

			if (rs.%Get("CKPYREFID") '= "")
			{
				set recId = rs.%Get("ID")
				set message = "ID#" _ recId
				set message = message _ "# CKPYREFID#" _ rs.%Get("CKPYREFID") _"# Status#" _ rs.%Get("Status")
				$$$TRACE("ID#" _ rs.%Get("ID"))

				QUIT
			}
		}
		if message = ""
		{
    		 $$$TRACE("No message in the queue")
    		 Quit 
		}
		$$$TRACE("Got a Message: " _ message)
		set list = ##class(IHC.ITF.DStruc.DndCoreEraRecord).%OpenId(recId)
		set list.Status = "InProcess"
		set list.ProcessTime = $ZDATETIME($HOROLOG,3, 1)
	  	set stat = list.%Save()
	  	$$$TRACE("Record Id: " _ recId _ " is InProcess, Save status:" _ stat)

		Set tSC = ..SendMessageToService(message)	   


	 } catch err
     {
	     if $GET(%objlasterror) '= ""
	    {
	        set errMsg =  $System.Status.GetErrorText(%objlasterror)
	    }
	    else
	    {
		    set errMsg = "No obj"
	    }
	    set alert = ##class(Ens.AlertRequest).%New()
	    set alert.AlertText = "Exception: Name: " _ err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " / Details: " _ errMsg
	    do ..BusinessHost.SendAlert(alert)
	    //$$$LOGALERT("Exception: Name: " _ err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " / Details: " _ errMsg)
	    Set tSC=$$$ERROR($$$GeneralError, err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " " _ errMsg)

    }

	Quit tSC
